files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #f0f0f0;
  --muted: #a0a0b0;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', sans-serif;
  font-size: 18px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border: 4px solid var(--accent);
  border-radius: 4px;
  padding: 32px 24px;
  width: 100%;
  max-width: 420px;
  text-align: center;
  box-shadow: 8px 8px 0 rgba(0,0,0,0.4);
}

h1 {
  font-size: 1.5rem;
  margin: 0 0 16px;
  letter-spacing: 2px;
  text-transform: uppercase;
}

#question {
  font-size: 2rem;
  font-weight: bold;
  margin: 16px 0 24px;
  min-height: 2.4em;
  display: flex;
  align-items: center;
  justify-content: center;
}

.answers {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin-bottom: 24px;
}

button {
  font-family: inherit;
  font-size: 1.1rem;
  font-weight: bold;
  color: var(--text);
  background: var(--bg);
  border: 3px solid var(--muted);
  border-radius: 4px;
  padding: 12px 24px;
  cursor: pointer;
  min-width: 80px;
  transition: background 0.1s, border-color 0.1s, transform 0.05s;
}

button:hover:not(:disabled) {
  background: var(--accent);
  border-color: var(--accent);
}

button:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

button:active:not(:disabled) {
  transform: translateY(2px);
}

button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.score-line {
  font-size: 1.1rem;
  margin: 0 0 24px;
  color: var(--muted);
}

#score { color: var(--accent); font-weight: bold; }

.controls {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

@media (max-width: 400px) {
  .card { padding: 24px 16px; }
  #question { font-size: 1.6rem; }
  button { padding: 10px 16px; font-size: 1rem; min-width: 64px; }
}

const questionEl = document.getElementById('question');
const answerA = document.getElementById('answer-a');
const answerB = document.getElementById('answer-b');
const scoreEl = document.getElementById('score');
const nextBtn = document.getElementById('next');
const restartBtn = document.getElementById('restart');

const QUESTIONS = [
  { text: '2 + 2 = ?', a: '4', b: '5', correct: 'a' },
  { text: '3 + 3 = ?', a: '5', b: '6', correct: 'b' }
];

let currentIndex = 0;
let score = 0;
let answered = false;
let finished = false;

function render() {
  if (finished) {
    questionEl.textContent = 'Finished';
    answerA.disabled = true;
    answerB.disabled = true;
    nextBtn.disabled = true;
    return;
  }
  const q = QUESTIONS[currentIndex];
  questionEl.textContent = q.text;
  answerA.textContent = q.a;
  answerB.textContent = q.b;
  answerA.setAttribute('aria-label', 'Answer A: ' + q.a);
  answerB.setAttribute('aria-label', 'Answer B: ' + q.b);
  answerA.disabled = false;
  answerB.disabled = false;
  nextBtn.disabled = false;
  answered = false;
}

function selectAnswer(choice) {
  if (answered || finished) return;
  answered = true;
  answerA.disabled = true;
  answerB.disabled = true;
  if (choice === QUESTIONS[currentIndex].correct) {
    score += 1;
    scoreEl.textContent = String(score);
  }
}

answerA.addEventListener('click', () => selectAnswer('a'));
answerB.addEventListener('click', () => selectAnswer('b'));

nextBtn.addEventListener('click', () => {
  if (!answered || finished) return;
  if (currentIndex < QUESTIONS.length - 1) {
    currentIndex += 1;
    render();
  } else {
    finished = true;
    render();
  }
});

restartBtn.addEventListener('click', () => {
  currentIndex = 0;
  score = 0;
  answered = false;
  finished = false;
  scoreEl.textContent = '0';
  render();
});

render();
